1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Quote of the Day</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
11	    font-family: Georgia, serif; background: linear-gradient(135deg, #1e3c72, #2a5298); color: #222;
12	  }
13	  .card {
14	    background: #fff; max-width: 560px; width: 90%; padding: 2rem; border-radius: 12px;
15	    box-shadow: 0 10px 30px rgba(0,0,0,.3); text-align: center;
16	  }
17	  h1 { margin: 0 0 1.5rem; font-size: 1rem; letter-spacing: .15em; text-transform: uppercase; color: #777; }
18	  blockquote { margin: 0 0 .5rem; font-size: 1.5rem; line-height: 1.4; min-height: 6rem; }
19	  .author { color: #555; font-style: italic; margin-bottom: 1.5rem; }
20	  button {
21	    font: inherit; padding: .6rem 1.4rem; border: 0; border-radius: 6px;
22	    background: #2a5298; color: #fff; cursor: pointer;
23	  }
24	  button:hover { background: #1e3c72; }
25	  .hint { margin-top: 1rem; font-size: .85rem; color: #888; }
26	  kbd { background: #eee; border: 1px solid #ccc; border-radius: 3px; padding: 0 .35em; }
27	</style>
28	</head>
29	<body>
30	<main class="card">
31	  <h1>Quote of the Day</h1>
32	  <blockquote id="quote" aria-live="polite"></blockquote>
33	  <div class="author" id="author"></div>
34	  <button id="new" type="button">New quote</button>
35	  <div class="hint">or press <kbd>N</kbd></div>
36	</main>
37	<script>
38	const quotes = [
39	  ["The only way to do great work is to love what you do.", "Steve Jobs"],
40	  ["Simplicity is the ultimate sophistication.", "Leonardo da Vinci"],
41	  ["What we think, we become.", "Buddha"],
42	  ["Well done is better than well said.", "Benjamin Franklin"],
43	  ["The journey of a thousand miles begins with a single step.", "Lao Tzu"],
44	  ["Knowing yourself is the beginning of all wisdom.", "Aristotle"],
45	  ["It always seems impossible until it's done.", "Nelson Mandela"],
46	  ["Stay hungry, stay foolish.", "Stewart Brand"],
47	  ["Whether you think you can or you can't, you're right.", "Henry Ford"],
48	  ["The best way to predict the future is to invent it.", "Alan Kay"],
49	  ["Not all those who wander are lost.", "J.R.R. Tolkien"],
50	  ["Do what you can, with what you have, where you are.", "Theodore Roosevelt"],
51	  ["Imagination is more important than knowledge.", "Albert Einstein"],
52	  ["Fall seven times, stand up eight.", "Japanese proverb"],
53	  ["In the middle of difficulty lies opportunity.", "Albert Einstein"],
54	  ["Action is the foundational key to all success.", "Pablo Picasso"],
55	  ["Quality is not an act, it is a habit.", "Will Durant"],
56	  ["Turn your wounds into wisdom.", "Oprah Winfrey"],
57	  ["Make it work, make it right, make it fast.", "Kent Beck"],
58	  ["Done is better than perfect.", "Sheryl Sandberg"]
59	];
60	
61	const quoteEl = document.getElementById("quote");
62	const authorEl = document.getElementById("author");
63	let current = -1;
64	
65	function newQuote() {
66	  let i;
67	  do { i = Math.floor(Math.random() * quotes.length); } while (i === current);
68	  current = i;
69	  quoteEl.textContent = "“" + quotes[i][0] + "”";
70	  authorEl.textContent = "— " + quotes[i][1];
71	}
72	
73	document.getElementById("new").addEventListener("click", newQuote);
74	document.addEventListener("keydown", e => {
75	  if (e.key.toLowerCase() === "n" && !e.ctrlKey && !e.metaKey && !e.altKey) newQuote();
76	});
77	newQuote();
78	</script>
79	</body>
80	</html>
